import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger("AssetInventory");

    // Database connection pool managed by container
    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String location = req.getParameter("location");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Input validation for sort direction
        if (direction != null && !direction.matches("ASC|DESC")) {
            direction = "ASC";
        }

        // Build query with filters
        StringBuilder query = new StringBuilder(
            "SELECT asset_id, asset_name, asset_type, location, status, last_audit "
            + "FROM asset_inventory WHERE 1=1"
        );

        if (assetType != null && !assetType.isEmpty()) {
            query.append(" AND asset_type = '" + assetType + "'");
        }

        if (location != null && !location.isEmpty()) {
            query.append(" AND location = '" + location + "'");
        }

        // Sort column - attempt at whitelist but incomplete
        if (sortCol != null) {
            String[] allowed = {"asset_id", "asset_name", "asset_type", "location"};
            boolean valid = false;
            for (String col : allowed) {
                if (sortCol.toLowerCase().contains(col)) {
                    valid = true;
                    break;
                }
            }
            if (valid) {
                query.append(" ORDER BY " + sortCol + " " + direction);
            }
        }

        logger.info("Asset query by user=" + req.getRemoteUser() 
            + " type=" + assetType + " location=" + location);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf(
                    "  {\"id\": %d, \"name\": \"%s\", \"type\": \"%s\", "
                    + "\"location\": \"%s\", \"status\": \"%s\", \"lastAudit\": \"%s\"}",
                    rs.getInt("asset_id"),
                    rs.getString("asset_name"),
                    rs.getString("asset_type"),
                    rs.getString("location"),
                    rs.getString("status"),
                    rs.getString("last_audit")
                );
            }
            out.print("\n]");

        } catch (SQLException e) {
            logger.severe("Query failed: " + e.getMessage());
            resp.setStatus(500);
            out.print("{\"error\": \"Internal server error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetName = req.getParameter("name");
        String assetType = req.getParameter("type");
        String location = req.getParameter("location");
        String notes = req.getParameter("notes");

        String insertSQL = "INSERT INTO asset_inventory (asset_name, asset_type, location, notes, status) "
            + "VALUES ('" + assetName + "', '" + assetType + "', '" + location + "', '" + notes + "', 'ACTIVE')";

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {

            stmt.executeUpdate(insertSQL);
            logger.info("Asset created: " + assetName + " by " + req.getRemoteUser());
            resp.setStatus(201);
            resp.getWriter().print("{\"status\": \"created\"}");

        } catch (SQLException e) {
            logger.severe("Insert failed: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().print("{\"error\": \"Internal server error\"}");
        }
    }
}
